+  { VMWARE_GET_VM_NAME,              "GET-VM-NAME" },
+  { VMWARE_VM_BIOS_UUID,             "VM-BIOS-UUID" },
+  { VMWARE_GET_VM_BIOS_UUID,         "GET-VM-BIOS-UUID" },
+  { VMWARE_VM_LOCATION_UUID,         "VM-LOCATION-UUID" },
+  { VMWARE_GET_VM_LOCATION_UUID,     "GET-VM-LOCATION-UUID" },
